namespace ghidra.app.plugin.core.label;




using docking.widgets.table;
using ghidra.program.model.symbol;

/**
 * Table model for showing label history.
 */
class LabelHistoryTableModel : AbstractSortedTableModel<LabelHistory> {
	private static readonly long serialVersionUID = 1L;

	static string ADDRESS = "Address";
	static string ACTION = "Action";
	static string LABEL = "Label";
	static string USER = "User";
	static string DATE = "Modification Date";

	// columns used in the getValueAt() method
	// Note: the address column may not exist
	private static int ADDRESS_COL = 0;
	private static int ACTION_COL = 1;
	private static int LABEL_COL = 2;
	private static int USER_COL = 3;
	private static int DATE_COL = 4;

	private string[] columnNames = new string[] { ADDRESS, ACTION, LABEL, USER, DATE };

	private int[] columnNumbers = new int[] { ADDRESS_COL, ACTION_COL, LABEL_COL, USER_COL, DATE_COL };

	private static string[] ACTION_NAMES = new string[] { "Add", "Remove", "Rename" };

	private List<LabelHistory> historyList;
	private bool showAddress;

	LabelHistoryTableModel(List<LabelHistory> list, bool showAddress) {
		historyList = list;
		this.showAddress = showAddress;
		if (!showAddress) {
			columnNames = new string[] { ACTION, LABEL, USER, DATE };
			columnNumbers = new int[] { ACTION_COL, LABEL_COL, USER_COL, DATE_COL };
		}
	}

	/* @Override */
	public string getName() {
		return "Label History";
	}

	/* (non Javadoc)
	 * @see javax.swing.table.TableModel#getRowCount()
	 */
	/* @Override */
	public int getRowCount() {
		return historyList.size();
	}

	/* (non Javadoc)
	 * @see javax.swing.table.TableModel#getColumnCount()
	 */
	/* @Override */
	public int getColumnCount() {
		return columnNames.length;
	}

	/* (non Javadoc)
	 * @see javax.swing.table.TableModel#getColumnClass(int)
	 */
	/* @Override */
	public Class<object> getColumnClass(int columnIndex) {
		if (columnNumbers[columnIndex] == DATE_COL) {
			return typeof(Date);
		}
		return typeof(string);
	}

	/* (non Javadoc)
	 * @see javax.swing.table.TableModel#getColumnName(int)
	 */
	/* @Override */
	public string getColumnName(int column) {
		return columnNames[column];
	}

	/* (non Javadoc)
	 * @see javax.swing.table.TableModel#isCellEditable(int, int)
	 */
	/* @Override */
	public bool isCellEditable(int rowIndex, int columnIndex) {
		return false;
	}

	int getDefaultSortColumn() {
		if (showAddress) {
			return ADDRESS_COL;
		}
		return columnNumbers.length - 1;
	}

	int getLabelColumn() {
		return columnNumbers.length - 3;
	}

	/* @Override */
	public bool isSortable(int columnIndex) {
		return true;
	}

	/* @Override */
	public List<LabelHistory> getModelData() {
		return historyList;
	}

	/* @Override */
	public object getColumnValueForRow(LabelHistory h, int columnIndex) {
		switch (columnNumbers[columnIndex]) {
			case ADDRESS_COL:
				return h.getAddress().toString();
			case ACTION_COL:
				return ACTION_NAMES[h.getActionID()];
			case LABEL_COL:
				return h.getLabelString();
			case USER_COL:
				return h.getUserName();
			case DATE_COL:
				return h.getModificationDate();
		}
		throw new ArrayIndexOutOfBoundsException("bad columnIndex");
	}
